// Live traffic notices generated by GitHub Actions from official Traffic Wales RSS.
(async function () {
  const target = document.getElementById('roadItems');
  if (!target) return;
  try {
    const res = await fetch('./traffic-feed.json?t=' + Date.now(), {cache:'no-store'});
    if (!res.ok) throw new Error('Traffic feed not yet published');
    const feed = await res.json();
    const stamp = Date.parse(feed.updated_at || '');
    if (!Number.isFinite(stamp) || Date.now() - stamp > 3 * 60 * 60 * 1000) throw new Error('Traffic feed is out of date');
    const notices = Array.isArray(feed.items) ? feed.items : [];
    target.replaceChildren();
    const note = document.createElement('p');
    note.className = 'sub';
    note.textContent = 'Traffic Wales · Checked ' + new Date(stamp).toLocaleString('en-GB', {dateStyle:'short',timeStyle:'short'}) + ' · Confirm before travelling';
    target.append(note);
    if (!notices.length) {
      const empty = document.createElement('p');
      empty.textContent = 'No matching Port Talbot-area notices in the current Traffic Wales feed. Check Traffic Wales for all alerts.';
      target.append(empty);
    }
    for (const item of notices.slice(0,12)) {
      const row = document.createElement('div'); row.className = 'item';
      const title = document.createElement('strong'); title.textContent = item.title || 'Traffic notice'; row.append(title);
      if (item.description) { const desc = document.createElement('small'); desc.textContent = item.description; row.append(desc); }
      try { const url = new URL(item.url); if (url.protocol === 'https:' && url.hostname.endsWith('traffic.wales')) {
        const link = document.createElement('a'); link.href = url.href; link.target='_blank'; link.rel='noopener noreferrer'; link.textContent='Official details ↗'; row.append(link);
      }} catch(e) {}
      target.append(row);
    }
  } catch(e) {
    // Keep existing manual notices; never present stale data as live.
    const note = document.createElement('p'); note.className='sub';
    note.textContent='Automatic traffic updates temporarily unavailable. Check Traffic Wales for current conditions.';
    target.prepend(note);
  }
})();
